var l=[{title:`Концентрична дія`,text:`М’яз створює силу, поки загалом вкорочується. У згинанні рук на біцепс згиначі ліктя вкорочуються, коли вага піднімається. Під час підйому з присідання кілька розгиначів стегна й коліна працюють, щоб підняти вас. «Концентрична» описує, що робить м’яз, а це не завжди те саме, що вправа виглядає як рух угору.`},{title:`Ексцентрична дія`,text:`М’яз створює силу, поки видовжується під навантаженням, часто гальмуючи рух. Опускання гантелі в згинанні рук чи сідання в присідання використовує ексцентричну дію основних робочих м’язів. Ця фаза допомагає силі й росту м’язів, але дуже незнайома ексцентрична робота може викликати сильну болючість. Нарощуйте її поступово й не перебільшуйте навмисно кожну фазу опускання.`},{title:`Ізометрична дія`,text:`М’яз створює силу без помітної зміни загальної довжини чи кута суглоба, який він контролює. Планки та стілець біля стіни є очевидними прикладами, а м’язи тулуба працюють приблизно ізометрично, коли ви тримаєте важке перенесення. Утримання в одному куті не є ідеальною заміною руху в повній амплітуді.`},{title:`Ролі змінюються залежно від завдання`,text:`Агоніст є основним учасником задуманої дії, а антагоніст протидіє їй або допомагає регулювати рух. Синергісти допомагають, а стабілізатори контролюють суглоби чи частини тіла. У віджиманні груди й трицепси виконують жим, а м’язи тулуба тримають вас вирівняними. Ці ролі залежать від руху, тож м’яз не має постійної мітки.`},{title:`Застосування на практиці`,text:`Опускайте з контролем, уникайте неконтрольованого відскоку й жміть чи тягніть у амплітуді, яку контролюєте. Утримання на час корисні, коли завдання не потребує руху, а динамічні повторення корисні, коли ви хочете силу в русі. У TrainUp кожна вправа задана повтореннями або часом утримання, а таймер утримання відстежує ваші утримання. Нотатки про техніку й темп допомагають робити хороші повторення, але повільніший рух не завжди дає швидші результати.`}];var i=[{label:`Позиційна заява ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Огляд механізмів м’язової гіпертрофії`,url:`https://pubmed.ncbi.nlm.nih.gov/37382939/`}];var n={sections:l,sources:i};export{n as default,l as sections,i as sources};